installer-gui-script.script:
function checkPowerPoint() {
  // Files, not system.applications: fromIdentifier() only finds a RUNNING app,
  // so with PowerPoint closed (which is how must-close leaves it) it reported
  // PowerPoint as not installed (Font Manager's installer, 2026-10-24).
  var home = system.env.HOME;
  // The wef folder lives in PowerPoint's sandbox container, which PowerPoint
  // creates the first time it runs. Its existence is the real test: PowerPoint
  // has run on this account, wherever the app itself lives. Making the folder
  // by hand before then is asking for a container macOS doesn't recognise.
  var container = !!home && system.files.fileExistsAtPath(home + '/Library/Containers/com.microsoft.Powerpoint');
  var app = system.files.fileExistsAtPath('/Applications/Microsoft PowerPoint.app') ||
    (!!home && system.files.fileExistsAtPath(home + '/Applications/Microsoft PowerPoint.app'));
  system.log('advanced-exporter: HOME=' + home + ' container=' + container + ' app=' + app);
  if (container || !home) return true; // no HOME: can't tell, so don't block on it
  my.result.type = 'Fatal';
  if (!app) {
    my.result.title = 'PowerPoint isn’t installed';
    my.result.message = 'Advanced Exporter is an add-in for Microsoft PowerPoint for Mac. Install PowerPoint, open it once, then run this installer again.';
  } else {
    my.result.title = 'Open PowerPoint once first';
    my.result.message = 'PowerPoint hasn’t been opened on this account yet, so it has nowhere to keep add-ins. Open PowerPoint, quit it, then run this installer again.';
  }
  return false;
}
